import type { DrizzleEnvSchema } from "@saflib/drizzle/env";
import type { EnvEnvSchema } from "@saflib/env/env";
import type { NodeEnvSchema } from "@saflib/node/env";

/**
 * Environment variables for the `@saflib/audit-rotator` package, including inherited variables via `extends`.
 * Generated by `@saflib/env`. To update, make changes to the adjacent `env.schema.json`, navigate to the package root, and run `npm exec saf-env generate`.
 */
export interface AuditRotatorEnvSchema extends DrizzleEnvSchema, EnvEnvSchema, NodeEnvSchema {
  /**
   * Google Cloud Storage bucket name for sealed audit SQLite archives (.sqlite.zst objects). Required in production. In local development, omit when using a disk-backed object store (e.g. USE_DISK_OBJECT_STORE=true); the seal pipeline must not upload to GCS without a non-empty bucket name outside NODE_ENV=test when using GCS.
   */
  AUDIT_ARCHIVE_BUCKET?: string;
  /**
   * Google Group email address that receives each audit seal digest (archive hash, chain tail, window bounds). Required in production. Optional in local development; the seal pipeline must not run without a non-empty value outside NODE_ENV=test.
   */
  AUDIT_DIGEST_RECIPIENT?: string;
  /**
   * How many days sealed audit archive files remain on local disk after a successful upload and digest email, before they may be deleted. Non-negative decimal integer as a string.
   */
  AUDIT_LOCAL_RETENTION_DAYS?: string;
}

/**
 * `process.env` casted to the `AuditRotatorEnvSchema` type.
 */
export const typedEnv = (globalThis.process ? process.env : {}) as unknown as AuditRotatorEnvSchema;
